import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { vendorAPI, apiCall } from '../../services/apiService';
import './VendorProfile.css';

const VendorProfile = () => {
  const [formData, setFormData] = useState({
    name: '',
    cuisineSpecialties: '',
    operatingRegion: '',
    menuHighlights: '',
    phoneNumber: '',
    businessAddress: ''
  });
  
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [hasExistingProfile, setHasExistingProfile] = useState(false);
  
  const navigate = useNavigate();

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    setIsLoading(true);
    const result = await apiCall(vendorAPI.getProfile);
    
    if (result.success && result.data) {
      setFormData({
        name: result.data.name || '',
        cuisineSpecialties: result.data.cuisineSpecialties || '',
        operatingRegion: result.data.operatingRegion || '',
        menuHighlights: result.data.menuHighlights || '',
        phoneNumber: result.data.phoneNumber || '',
        businessAddress: result.data.businessAddress || ''
      });
      setHasExistingProfile(true);
    }
    
    setIsLoading(false);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    if (error) setError('');
    if (success) setSuccess('');
  };

  const validateForm = () => {
    const { name, cuisineSpecialties, operatingRegion, phoneNumber } = formData;
    
    if (!name.trim()) {
      setError('Business name is required');
      return false;
    }
    
    if (!cuisineSpecialties.trim()) {
      setError('Cuisine specialties are required');
      return false;
    }
    
    if (!operatingRegion.trim()) {
      setError('Operating region is required');
      return false;
    }
    
    if (operatingRegion !== 'Chennai' && operatingRegion !== 'Bangalore') {
      setError('Operating region must be either Chennai or Bangalore');
      return false;
    }
    
    if (phoneNumber && !/^\+?[\d\s\-\(\)]{10,15}$/.test(phoneNumber.trim())) {
      setError('Please enter a valid phone number');
      return false;
    }
    
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    
    if (!validateForm()) {
      return;
    }
    
    setIsSaving(true);
    
    const result = await apiCall(vendorAPI.createProfile, formData);
    
    if (result.success) {
      setSuccess(hasExistingProfile ? 'Profile updated successfully!' : 'Profile created successfully!');
      setHasExistingProfile(true);
      
      setTimeout(() => {
        navigate('/vendor/dashboard');
      }, 2000);
    } else {
      setError(result.error);
    }
    
    setIsSaving(false);
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading profile...
      </div>
    );
  }

  return (
    <div className="vendor-profile">
      <div className="page-header">
        <div className="container">
          <h1>{hasExistingProfile ? 'Edit Profile' : 'Complete Your Profile'}</h1>
          <p>Provide your food truck business information</p>
        </div>
      </div>

      <div className="container">
        <div className="profile-form-container">
          <form onSubmit={handleSubmit} className="profile-form">
            {error && (
              <div className="alert alert-error">
                {error}
              </div>
            )}
            
            {success && (
              <div className="alert alert-success">
                {success}
              </div>
            )}

            <div className="form-section">
              <h2>Business Information</h2>
              
              <div className="form-group">
                <label htmlFor="name" className="form-label">
                  Business Name *
                </label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  className="form-control"
                  placeholder="Enter your food truck business name"
                  disabled={isSaving}
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="cuisineSpecialties" className="form-label">
                  Cuisine Specialties *
                </label>
                <input
                  type="text"
                  id="cuisineSpecialties"
                  name="cuisineSpecialties"
                  value={formData.cuisineSpecialties}
                  onChange={handleChange}
                  className="form-control"
                  placeholder="e.g., Indian, Italian, Street Food"
                  disabled={isSaving}
                  required
                />
                <small className="form-help">
                  Separate multiple cuisines with commas
                </small>
              </div>

              <div className="form-group">
                <label htmlFor="operatingRegion" className="form-label">
                  Operating Region *
                </label>
                <select
                  id="operatingRegion"
                  name="operatingRegion"
                  value={formData.operatingRegion}
                  onChange={handleChange}
                  className="form-control"
                  disabled={isSaving}
                  required
                >
                  <option value="">Select your operating region</option>
                  <option value="Chennai">Chennai</option>
                  <option value="Bangalore">Bangalore</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="menuHighlights" className="form-label">
                  Menu Highlights
                </label>
                <textarea
                  id="menuHighlights"
                  name="menuHighlights"
                  value={formData.menuHighlights}
                  onChange={handleChange}
                  className="form-control"
                  placeholder="Describe your popular dishes and specialties"
                  rows="4"
                  disabled={isSaving}
                />
              </div>
            </div>

            <div className="form-section">
              <h2>Contact Information</h2>
              
              <div className="form-group">
                <label htmlFor="phoneNumber" className="form-label">
                  Phone Number
                </label>
                <input
                  type="tel"
                  id="phoneNumber"
                  name="phoneNumber"
                  value={formData.phoneNumber}
                  onChange={handleChange}
                  className="form-control"
                  placeholder="+91 9876543210"
                  disabled={isSaving}
                />
              </div>

              <div className="form-group">
                <label htmlFor="businessAddress" className="form-label">
                  Business Address
                </label>
                <textarea
                  id="businessAddress"
                  name="businessAddress"
                  value={formData.businessAddress}
                  onChange={handleChange}
                  className="form-control"
                  placeholder="Enter your business address or main operating location"
                  rows="3"
                  disabled={isSaving}
                />
              </div>
            </div>

            <div className="form-actions">
              <button
                type="button"
                onClick={() => navigate('/vendor/dashboard')}
                className="btn btn-secondary"
                disabled={isSaving}
              >
                Cancel
              </button>
              
              <button
                type="submit"
                className="btn btn-primary"
                disabled={isSaving}
              >
                {isSaving ? (
                  <>
                    <span className="loading-spinner"></span>
                    Saving...
                  </>
                ) : (
                  hasExistingProfile ? 'Update Profile' : 'Create Profile'
                )}
              </button>
            </div>
          </form>

          <div className="profile-help">
            <h3>Why do we need this information?</h3>
            <ul>
              <li><strong>Business Name:</strong> This will be displayed to customers</li>
              <li><strong>Cuisine Specialties:</strong> Helps customers find your type of food</li>
